import 'package:flutter/material.dart';import '../services/api.dart';import '../services/store.dart';import '../widgets/result.dart';class InterviewPage extends StatefulWidget{const InterviewPage({super.key});@override State<InterviewPage> createState()=>_S();}class _S extends State<InterviewPage>{final resume=TextEditingController(text:Store.resume),job=TextEditingController(),question=TextEditingController(),answer=TextEditingController();String out='';bool busy=false;Future<void> run(String path)async{setState(()=>busy=true);try{final r=await Api.post(path,{'resume_text':resume.text,'job_description':job.text,'question':question.text,'answer':answer.text});out=r.values.first.toString();await Store.log('Interview tool');}catch(e){out='Error: $e';}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Interview Practice')),body:ListView(padding:const EdgeInsets.all(14),children:[TextField(controller:resume,minLines:3,maxLines:7,decoration:const InputDecoration(labelText:'Resume')),TextField(controller:job,minLines:4,maxLines:9,decoration:const InputDecoration(labelText:'Job description')),FilledButton(onPressed:busy?null:()=>run('/interview/questions'),child:const Text('Generate 8 questions')),const Divider(),TextField(controller:question,minLines:2,maxLines:4,decoration:const InputDecoration(labelText:'Question you are practicing')),TextField(controller:answer,minLines:4,maxLines:8,decoration:const InputDecoration(labelText:'Your answer')),OutlinedButton(onPressed:busy?null:()=>run('/interview/feedback'),child:const Text('Feedback on my answer')),if(busy)const LinearProgressIndicator(),if(out.isNotEmpty)Result(title:'Practice',text:out)]));}
